import sys
input = sys.stdin.read
data = input().split()

index = 0
T = int(data[index])
index += 1
results = []

for _ in range(T):
    N = int(data[index])
    K = int(data[index + 1])
    index += 2

    if K > N // 2:
        results.append(-1)
    else:
        permutation = list(range(1, N + 1))
        for i in range(K):
            permutation[i], permutation[N - 1 - i] = permutation[N - 1 - i], permutation[i]
        results.append(permutation)

for result in results:
    if result == -1:
        print(-1)
    else:
        print(" ".join(map(str, result)))
